head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[dataMap > M > setEmptyValue]<br/>DataMap 모듈의 전체 Key 의 값(Value)을 ''(Empty String)으로 설정합니다.",
    "validation" : [
        "Key 의 defaultValue 속성이 설정된 경우 defaultValue 속성값이 설정됩니다.",
        "값(Value)이 새로 설정된 Key 의 '변경여부' 상태값은 firstSet 속성과 원본값(Origin Value) 할당 여부에 따라 달라집니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {   
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        $p.data.remove("target1");
    }

    if (typeof input1 !== 'undefined') {
        input1.remove();
    }  

    // // 조건 설정       
    // let properties = {

    // };

    // let cList = $c.gcm.createCList(properties);  

    // target 생성
    $c.gcm.createBasicDataMap();

    // input 생성
    $c.gcm.createEmptyInput('ref="data:target1.key1" style="width:200px;"', '', 'input1');  

    scwin.btn_getJSON_onclick();
    scwin.btn_getModifiedJSON_onclick();
}   



scwin.btn_getJSON_onclick = function (e) {
    let rtn = target1.getJSON();
    let jsonString = JSON.stringify(rtn);

    wf_body_bottom.getObj("scwin").setReturnValue("getJSON : " + jsonString);  
};



scwin.btn_getModifiedJSON_onclick = function (e) {
    let rtn = target1.getModifiedJSON();
    let jsonString = JSON.stringify(rtn);

    wf_body_bottom.getObj("scwin").setReturnValue("getModifiedJSON : " + jsonString);  
}



scwin.btn_setEmptyValue_onclick = function (e) {   
    target1.setEmptyValue();

    scwin.btn_getJSON_onclick();
    scwin.btn_getModifiedJSON_onclick();
};
